"""Generator speed work (038) must not change a single generated byte."""

from __future__ import annotations

import hashlib
from datetime import date

import pytest
from hypothesis import given
from hypothesis import strategies as st

from scruple.hashing import canonical_json
from scruple.sim.difficulty import difficulty_mix
from scruple.sim.disputes import (
    DEFAULT_MIX,
    FULL_MIX,
    CaseMix,
    generate_cases,
    generate_sharded,
    shard_seed,
)
from scruple.sim.evidence import EvidenceKind, seal, seal_reference

# sha256 over canonical JSON of generate_cases(seed, 3000, mix) for seeds 1, 7, 123456789,
# recorded with the generator as it was before the 038 optimisations.
GOLDEN = {
    "default": "3133ac3a564a72bbba5c0c8becdbef98f71fe1919297b340faf6cb6cb2611744",
    "full": "df6780b045c970abed2b98fd2846a3afe5969d51d63272beadd85bc337b32a94",
    "hard": "9fa44cb2003c7f6b9147fd7742c208596814c290601e20cb6f11e606be5a0d00",
}
MIXES: dict[str, CaseMix] = {
    "default": DEFAULT_MIX,
    "full": FULL_MIX,
    "hard": difficulty_mix(1.0),
}


@pytest.mark.parametrize("name", sorted(GOLDEN))
def test_generated_bytes_are_unchanged(name: str) -> None:
    h = hashlib.sha256()
    for seed in (1, 7, 123456789):
        for c in generate_cases(seed, 3000, MIXES[name]):
            h.update(canonical_json(c.model_dump(mode="json")).encode())
    assert h.hexdigest() == GOLDEN[name]


text = st.text(max_size=12)


@given(
    text,
    st.sampled_from(list(EvidenceKind)),
    st.dates(min_value=date(1990, 1, 1), max_value=date(2100, 1, 1)),
    st.dictionaries(text, text, max_size=6),
)
def test_fast_seal_equals_the_reference(
    case_id: str, kind: EvidenceKind, day: date, fields: dict[str, str]
) -> None:
    assert seal(case_id, kind, day, fields) == seal_reference(case_id, kind, day, fields)


def test_seal_falls_back_for_non_strings() -> None:
    odd: dict[str, str] = {"amount_minor": 5}  # type: ignore[dict-item]
    d = date(2026, 1, 1)
    assert seal("c", EvidenceKind.RECEIPT, d, odd) == seal_reference(
        "c", EvidenceKind.RECEIPT, d, odd
    )


def test_generated_documents_carry_valid_seals() -> None:
    for c in generate_cases(3, 400, FULL_MIX):
        forged = set(c.truth.forged)
        for d in c.documents:
            assert d.content_hash == seal_reference(d.case_id, d.kind, d.issued_on, d.fields) or (
                d.doc_id in forged
            )


def test_sharded_generation_ignores_worker_count() -> None:
    one = generate_sharded(5, 900, FULL_MIX, shard_size=200, workers=1)
    two = generate_sharded(5, 900, FULL_MIX, shard_size=200, workers=2)
    assert [c.model_dump() for c in one] == [c.model_dump() for c in two]
    assert len(one) == 900 and len({c.case_id for c in one}) == 900
    assert one[0].case_id == "cd-5s0-000000" and one[-1].case_id == "cd-5s4-000099"


def test_shards_use_derived_seeds() -> None:
    cases = generate_sharded(9, 30, DEFAULT_MIX, shard_size=10, workers=1)
    want = generate_cases(shard_seed(9, 1), 10, DEFAULT_MIX, id_prefix="9s1")
    assert cases[10:20] == want
    assert len({shard_seed(9, k) for k in range(1000)}) == 1000


@pytest.mark.parametrize(("n", "size"), [(-1, 10), (5, 0)])
def test_sharded_validates(n: int, size: int) -> None:
    with pytest.raises(ValueError, match="shard_size"):
        generate_sharded(1, n, shard_size=size)


def test_sharded_empty() -> None:
    assert generate_sharded(1, 0) == []
